package ru.voicerooms;import static org.junit.Assert.*;import org.junit.Test;public class SessionTokenTest {  @Test  public void acceptsOnlyTheSignedSessionShape() {    assertTrue(SessionToken.isValid("eyJpZCI6MX0.signature"));    for (String value : new String[] {"", "plain", "a.b.c", "a/b.c", "a\\b.c", "a.b\n"})      assertFalse(SessionToken.isValid(value));    assertFalse(SessionToken.isValid(null));  }}